package com.lbos.commercecustomer.service;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lbos.commercecustomer.dto.request.CategoryRequest;import com.lbos.commercecustomer.entity.*;import com.lbos.commercecustomer.enums.CategoryStatus;import com.lbos.commercecustomer.exception.*;import com.lbos.commercecustomer.mapper.CommerceMapper;import com.lbos.commercecustomer.repository.*;import com.lbos.commercecustomer.service.impl.*;import java.util.*;import org.junit.jupiter.api.Test;class CategoryServiceImplTest{@Test void createPositive(){var r=mock(ProductCategoryRepository.class);when(r.save(any())).thenAnswer(x->{ProductCategory e=x.getArgument(0);e.setId(1L);return e;});var s=new CategoryServiceImpl(r,mock(ProductRepository.class),new CommerceMapper());assertEquals("Food",s.create(new CategoryRequest("Food","Daily food",CategoryStatus.ACTIVE)).name());}@Test void duplicateNegative(){var r=mock(ProductCategoryRepository.class);when(r.existsByNameIgnoreCase("Food")).thenReturn(true);var s=new CategoryServiceImpl(r,mock(ProductRepository.class),new CommerceMapper());assertThrows(DuplicateResourceException.class,()->s.create(new CategoryRequest("Food","Daily food",CategoryStatus.ACTIVE)));}@Test void referencedDeleteBlocked(){var r=mock(ProductCategoryRepository.class);var p=mock(ProductRepository.class);var c=new ProductCategory();c.setId(1L);var x=new Product();x.setCategory(c);when(r.findById(1L)).thenReturn(Optional.of(c));when(p.findAll()).thenReturn(List.of(x));var s=new CategoryServiceImpl(r,p,new CommerceMapper());assertThrows(BusinessValidationException.class,()->s.delete(1L));}}